const MISSION_IMAGE_DESCRIPTIONS=["A brick robot with raised wheels tests paper colors beside a tablet.", "A brick robot on a floor lane beside a ruler and distance markers.", "Two different parcel holders, loose building parts and the same paper parcel.", "A close-up of a color sensor over red, white and blue paper under a lamp.", "An overhead route plan with arrow cards, a robot and a delivery space.", "A robot wheel and downward-facing sensor stopped at a broad red floor line.", "A robot carrying a paper parcel into a marked delivery space.", "A classroom display of the finished robot, earlier holders and test results."];
const VISUALS=COURSE.lessons.map((l,i)=>[l.title,l.objective,MISSION_IMAGE_DESCRIPTIONS[i]]);
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let activeLesson=1, program=[],state=Rover.initial(),timer=null,trials=[],prediction='';
function download(name,text,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function showView(name){if(name!=='course')document.querySelectorAll('audio').forEach(a=>a.pause());document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==name+'-view');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name!=='lab')pause();}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('#missions').innerHTML=COURSE.lessons.map(l=>`<button class="mission" data-lesson="${l.id}"><img class="mission-image" src="images/mission-${l.id}.png?v=module-art-1" alt="${VISUALS[l.id-1][2]}" loading="lazy"><span class="eyebrow">MISSION ${String(l.id).padStart(2,'0')}</span><h3>${l.title}</h3><p>${l.mission}</p><span>Open interactive lesson →</span></button>`).join('');
document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{renderLesson(+b.dataset.lesson);$('#lesson').focus();});
function buildChoicesHTML(){return `<section class="build-choice-section"><h3>Choose one build</h3><p>Use the same robot base. Open a choice to read its instructions, then use its worksheet pages for your tests.</p><div class="build-choice-grid">${COURSE.buildChoices.map((c,i)=>`<details class="build-choice"><summary>${i+1}. ${esc(c.title)}</summary><p>${esc(c.make)}</p><p><strong>Materials:</strong> ${c.materials.map(esc).join('; ')}.</p><h4>Build steps</h4><ol>${c.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h4>Program</h4>${c.code.map(t=>`<p>${esc(t)}</p>`).join('')}<h4>What counts as success?</h4><ul>${c.checks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a class="btn primary" href="workbooks/module-8.pdf#page=${5+4*i}" target="_blank">Open choice ${i+1} workbook</a><p class="small">Print pages ${5+4*i}-${8+4*i} for this build, or use the ready-to-print class packets in the Teacher Desk.</p></details>`).join('')}</div></section>`;}
function renderLesson(id){activeLesson=id;const l=COURSE.lessons[id-1];$('#lesson').innerHTML=`<div class="section-label">MISSION ${id} · TWO 45-MINUTE SESSIONS</div><h2>${l.title}</h2><p class="lead">${l.mission}</p><section id="interactive-slides" class="lesson-player" aria-label="Interactive lesson slides"></section><details class="lesson-reference"><summary>Lesson directions and downloads</summary><figure class="lesson-visual"><img src="images/mission-${id}.png?v=module-art-1" alt="${VISUALS[id-1][2]}"><figcaption><span class="eyebrow">LOOK CLOSER</span><h3>${VISUALS[id-1][0]}</h3><p>${VISUALS[id-1][1]}</p><small>This picture shows an idea. Follow LEGO’s instructions to build the real robot.</small></figcaption></figure><div class="note"><strong>What you will learn</strong><p>${l.objective}</p></div><div class="cols"><div><h3>Words to know</h3><dl class="word-list">${l.words.map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl><h3>The idea</h3><p>${l.concept}</p><h3>Build & test</h3><ol>${l.build.map(s=>`<li>${s}</li>`).join('')}</ol></div><aside><h3>On your workbench</h3><p>${l.parts}</p><h3>What counts as success?</h3><p>${l.success}</p><h3>Make it a fair test</h3><p>${l.variables}</p><a class="btn primary" href="workbooks/module-${id}.pdf" target="_blank">Open this module's workbook</a><a class="btn" href="programs/lesson-${id}.html" target="_blank">Open coding guide</a><p class="small">Coding Canvas is LEGO’s coding app. These are written steps. Your teacher must make and test the program on the real robot before class.</p><h3>Listen to Amy</h3><audio controls preload="none" src="audio/lesson-${id}.wav?v=chipper-20260910">${l.narration}</audio><details><summary>Read the audio words</summary><p>${l.narration}</p></details></aside></div><div class="cols"><div class="note"><h3>Pause & explain</h3><p>${l.question}</p><details><summary>Read an example answer</summary><p>${l.answer}</p></details></div><div><h3>If it doesn’t work</h3><p>${l.fix}</p><p><strong>Watch for this:</strong> ${l.misconception}</p><details><summary>Take it further</summary><p>${l.extend}</p></details></div></div><div class="actions"><a class="btn" href="workbooks/module-${id}.pdf">Module ${id} student workbook</a><a class="btn" href="workbooks/index.html">Print by class</a><button class="btn" id="to-lab">Try the Mission simulator →</button>${id<8?'<button class="btn primary" id="next">Next mission →</button>':''}</div></details>`;LessonPlayer.mount($('#interactive-slides'),id);$('#to-lab').onclick=()=>showView('lab');if($('#next'))$('#next').onclick=()=>{renderLesson(id+1);$('#lesson').focus();};document.querySelectorAll('[data-lesson]').forEach(b=>b.classList.toggle('selected',+b.dataset.lesson===id));}
$('#teacher-view').innerHTML=`<div class="section-label">READY FOR YOUR CLASSROOM</div><h1>The teacher workbench</h1><p class="lead">A teaching draft with lesson directions, test notes and a scoring guide. Build and test each program on your real kit before class.</p><div class="actions"><a class="btn primary" href="teacher-guide.pdf">Teacher guide & answer key</a><a class="btn" href="workbooks/index.html">Print student packets</a><a class="btn" href="starter-programs.zip">All 8 sets of coding steps</a></div><h2>Print for today's class</h2><p>Every class packet begins with Name, Date and Period. Use US Letter, actual size (100%), two-sided, flip on long edge. Modules 1–7 use two sheets for class 1 and one sheet for class 2. Final-build class packets use two sheets each.</p><div class="actions"><a class="btn primary" href="workbooks/index.html">Choose module and class</a><a class="btn" href="student-workbooks.zip">Download all class packets</a></div><h2>Set up the room</h2><details class="room-setup" id="room-setup"><summary>See an example classroom setup — hover, focus or tap</summary><figure><img src="images/classroom-setup.svg" alt="Example classroom plan for 24 students: six team tables, three shared floor test lanes, a teacher demonstration table and a clear walkway to the exit."><figcaption>Six teams of four. Teams 1–2 share lane A, 3–4 share lane B, and 5–6 share lane C. Run only one robot in each lane at a time. Keep the walkway and exit clear. This is a planning example, not a scale drawing.</figcaption></figure><div class="actions"><a class="btn" href="images/classroom-setup.svg" target="_blank">Open full-size plan</a><a class="btn" href="classroom-setup.pdf" target="_blank">Print room plan</a></div></details><section class="ready-materials"><h3>Everything to read and print</h3><p>Use the materials below with the kit and ordinary craft supplies. Students can read the coding guides directly in the course.</p><div class="actions"><a class="btn primary" href="classroom-materials.pdf">Classroom materials pack</a><a class="btn" href="course-materials.zip">Download all printable materials</a></div><p>The pack includes team roles, arrow cards, color cards, a paper-parcel template, setup directions and first-class teaching notes. Use LEGO’s free Coding Canvas with the physical kit; it is separate from this screen simulator.</p></section><ol>${COURSE.setup.map(s=>`<li>${s}</li>`).join('')}</ol><h2>Two sessions per mission</h2>${COURSE.routine.map(s=>`<p>${s}</p>`).join('')}<h2>Check what students learned</h2><p>Ask each student to explain the robot’s job, how the code works, what the tests showed and why they made a change. The teacher guide has a scoring table, also called a rubric.</p><h2>Plan the kit budget</h2><p>US prices checked September 10, 2026. The cost sheet is at the back of both PDFs.</p><div class="scroll"><table><thead><tr><th>Option</th><th>USD</th><th>Basis</th></tr></thead><tbody>${COURSE.cost.rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>${COURSE.cost.note}</p><h2>Imagine your delivery mission</h2><img src="rover.png" alt="A classroom-style illustration of a yellow and blue brick robot carrying a paper parcel" style="width:100%;max-width:850px;border-radius:24px"><p class="small">These images were made with AI to show project ideas. They do not show the exact parts in set #45522. Use LEGO’s instructions and a base your teacher has checked. This independent course is not endorsed by the LEGO Group.</p><h2>Word help</h2><p>Use these meanings when explaining a new word. Each lesson also has its own short word list.</p><dl class="word-list">${COURSE.glossary.map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl><h2>Sources & credits</h2><ul>${COURSE.sources.map(s=>`<li><a href="${s[1]}" target="_blank" rel="noopener">${s[0]}</a></li>`).join('')}</ul><p>The audio was made using Amy Sullivan’s own voice clone. The lessons and coding steps were written for this course. The screen robot follows rules on a grid. It cannot check how real wheels and sensors work. This course still needs tests on a real robot and in a classroom.</p>`;
$('#lab-view').innerHTML=`<div class="section-label">PLAN · PREDICT · TEST · IMPROVE</div><h1>Mission simulator</h1><p class="lead">Write a route. Explain a decision. Learn from the run.</p><div class="note">A simulator is a way to try an idea on a screen. This screen robot checks the next square for a wall. Your real LEGO robot reads floor colors, so it works differently. Here, a move is one square and a turn is a quarter-turn. Test the real robot’s wheels, colors and stopping on the floor.</div><div class="lab-grid"><section class="panel"><label for="map"><strong>Choose a mission</strong></label><select id="map">${Rover.maps.map((m,i)=>`<option value="${i}">${i+1}. ${m.name}</option>`).join('')}</select><div id="board" class="board" role="img" aria-label="Eight by eight delivery route"></div><p class="small">Your robot faces north when it starts. North is up on this map.</p><div id="status" class="status" role="status" aria-live="polite"></div><div class="actions"><button class="btn primary" id="run">Run</button><button class="btn" id="step">One step</button><button class="btn" id="pause">Pause</button><button class="btn" id="reset">Start over</button></div></section><section class="panel"><h2>Your program</h2><p>A command is one instruction. Click to add it. Use the arrows to change the order. You can add up to 40. “If blocked” means: if the next square has a wall or is outside the grid, turn right. Otherwise, move forward.</p><div class="actions">${Object.entries(Rover.labels).map(([k,v])=>`<button class="btn mini" data-add="${k}">${v}</button>`).join('')}</div><ol id="program" class="program"></ol><button class="btn" id="clear">Clear program</button><label for="prediction"><h3>What do you think will happen?</h3></label><textarea id="prediction" rows="3" placeholder="Where will the robot finish? What will it do if a wall is ahead?"></textarea><details><summary>Need a starting hint?</summary><p id="hint"></p></details></section></div><section class="panel"><h2>What happened in this run</h2><div style="overflow:auto"><table><thead><tr><th>Step</th><th>Command</th><th>Next square</th><th>Column, row</th><th>Facing</th></tr></thead><tbody id="trace"></tbody></table></div><div class="actions"><button class="btn" id="record">Save test result</button><button class="btn" id="export">Download test notes</button></div><p id="trial-count">No tests saved yet.</p><p class="small">Your notes stay in this open page. Download them before you close or refresh it. The page does not send your notes anywhere.</p></section>`;
function pause(){if(timer)clearInterval(timer);timer=null;}
function reset(){pause();state=Rover.initial(+$('#map').value);draw();}
function draw(){const m=Rover.maps[state.map];BrickGame.paintBoard(m,state);$('#board').setAttribute('aria-label',`8 by 8 grid. Rover column ${state.x}, row ${state.y}, facing ${['north','east','south','west'][state.h]}. Delivery bay ${m.goal.join(', ')}. Next square ${Rover.blocked(state)?'blocked':'clear'}.`);$('#status').textContent=state.message;$('#hint').textContent=m.hint;$('#program').innerHTML=program.map((c,i)=>`<li ${i===state.pc&&state.status==='running'?'aria-current="step"':''}>${Rover.labels[c]} <button class="mini" data-up="${i}" aria-label="Move command ${i+1} up" ${i===0?'disabled':''}>↑</button> <button class="mini" data-down="${i}" aria-label="Move command ${i+1} down" ${i===program.length-1?'disabled':''}>↓</button> <button class="mini" data-remove="${i}" aria-label="Remove command ${i+1}">×</button></li>`).join('')||'<p>Add your first command above.</p>';$('#trace').innerHTML=state.trace.map(t=>`<tr><td>${t.step}</td><td>${t.command}</td><td>${t.sensor}</td><td>${t.x}, ${t.y}</td><td>${t.heading}</td></tr>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{program.splice(+b.dataset.remove,1);reset();});for(const dir of ['up','down'])document.querySelectorAll(`[data-${dir}]`).forEach(b=>b.onclick=()=>{let i=+b.dataset[dir],j=i+(dir==='up'?-1:1);[program[i],program[j]]=[program[j],program[i]];reset();});}
function advance(){if(!program.length){$('#status').textContent='Add a command before running.';pause();return;}const previous=state;BrickGame.begin(previous);state=Rover.step(state,program);draw();BrickGame.react(previous,state);if(state.status!=='running')pause();}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(program.length>=40){$('#status').textContent='You have 40 steps. Change or remove one before adding another.';return;}program.push(b.dataset.add);reset();});$('#map').onchange=()=>{program=[];reset();};$('#run').onclick=()=>{pause();if(['finished','collision','stopped'].includes(state.status))state=Rover.initial(state.map);advance();if(state.status==='running')timer=setInterval(advance,650);};$('#step').onclick=()=>{pause();advance();};$('#pause').onclick=()=>{pause();$('#status').textContent='Paused. Step or run to continue.';};$('#reset').onclick=reset;$('#clear').onclick=()=>{program=[];reset();};$('#record').onclick=()=>{if(!state.steps){$('#status').textContent='Run at least one step before saving a test result.';return;}trials.push({trial:trials.length+1,mission:Rover.maps[state.map].name,prediction:$('#prediction').value,program:program.join(' '),status:state.status,success:Rover.atGoal(state)&&['finished','stopped'].includes(state.status),steps:state.steps,x:state.x,y:state.y});BrickGame.record(state,trials[trials.length-1]);$('#trial-count').textContent=`${trials.length} test(s) saved. Download your notes before leaving.`;};$('#export').onclick=()=>{if(!trials.length){$('#trial-count').textContent='Save a test result first.';return;}const keys=Object.keys(trials[0]),quote=v=>'"'+String(v).replace(/"/g,'""')+'"';download('rover-trial-log.csv',[keys.join(','),...trials.map(t=>keys.map(k=>quote(t[k])).join(','))].join('\r\n'),'text/csv');};
function setupRoomPreview(){const box=document.querySelector('#room-setup'),summary=box.querySelector('summary');let pinned=false;box.addEventListener('pointerenter',ev=>{if(ev.pointerType==='mouse')box.open=true;});box.addEventListener('pointerleave',()=>{if(!pinned&&!box.contains(document.activeElement))box.open=false;});summary.addEventListener('focus',()=>box.open=true);summary.addEventListener('click',ev=>{ev.preventDefault();pinned=!pinned;box.open=pinned;});box.addEventListener('focusout',()=>setTimeout(()=>{if(!pinned&&!box.contains(document.activeElement)&&!box.matches(':hover'))box.open=false;},0));box.addEventListener('keydown',ev=>{if(ev.key==='Escape'){pinned=false;box.open=false;summary.focus();box.open=false;}});}
BrickGame.setup();setupRoomPreview();renderLesson(1);draw();
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'read_rover_lab',description:'Read the current educational rover simulator state and program. Does not change the course.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({content:[{type:'text',text:JSON.stringify({state,program})}]})});}catch(e){console.info('Optional course tool registration unavailable.');}}

